  type Env = KindEnv

  /** My binding type. */
  type EnvBinding = KindBinding

  /** Extend me with the immediate bindings of the given node. */
  def extend(node: Node): KindEnv =
    new NestedKindEnv(this, KindEnv.extractNodeBindings(node))

  /** Extend me with the immediate bindings of the given nodes. */
  def extend[T <: Node](nodes: Iterable[T]): KindEnv =
    new NestedKindEnv(this, nodes.flatMap(KindEnv.extractNodeBindings))

  /** Extend me with the immediate bindings of the given node. */
  def extend(node: Node, where: Option[WhereClause]): KindEnv = {
    val whereBindings = where.map(KindEnv.extractNodeBindings)
                             .getOrElse(Iterable.empty)
    val nodeBindings = KindEnv.extractNodeBindings(node)
    val declared = whereBindings ++ nodeBindings
    new NestedKindEnv(this, declared ++ KindEnv.constraintBounds(this, declared, where))
  }

  /** Extend me with the immediate bindings of the given nodes. */
  def extend[T<:Node](nodes: Iterable[T], where: Option[WhereClause]): KindEnv = {
    val whereBindings = where.map(KindEnv.extractNodeBindings)
                             .getOrElse(Iterable.empty)
    val nodesBindings = nodes.flatMap(KindEnv.extractNodeBindings)
    val declared = whereBindings ++ nodesBindings
    new NestedKindEnv(this, declared ++ KindEnv.constraintBounds(this, declared, where))
  }

  /**
   * Get the type of the given variable name, if it is bound. The resulting
   * type will only be defined if this name maps to a bool, int, or nat static
   * parameter.
   */
  def getType(x: Name): Option[Type] = lookup(x).flatMap(b =>
    b.sparam.getKind match {
      case _:KindBool => Some(Types.BOOLEAN)
      case _:KindInt => Some(Types.INT_LITERAL)
      case _:KindNat => Some(Types.INT_LITERAL)
      case _ => None
    })

  def staticParam(x: Name): Option[StaticParam] = lookup(x).map(_.sparam)
}

/** The single empty kind environment. */
protected object EmptyKindEnv extends KindEnv with EmptyStaticEnv[StaticParam] {
  // A type opened from a value is found in every environment, as a size
  // opened from a value needs no binding.
  override def lookup(x: Name): Option[KindBinding] = KindEnv.lookupOpened(x)
}

/**
 * A kind environment with a parent and some explicit bindings.
 *
 * @param parent A kind environment that this one extends.
 * @param _bindings A collection of all the bindings in this environment.
 */
class NestedKindEnv (protected val parent: KindEnv,
                               _bindings: Iterable[KindBinding])
    extends KindEnv with NestedStaticEnv[StaticParam] {

  /** Internal representation of `bindings` is a map. */
  val bindings: Map[Name, KindBinding] =
    Map(_bindings.map(b => (b.name, b)).toSeq:_*)
}

/** Companion module for KindEnv; contains "static" members. */
object KindEnv extends StaticEnvCompanion[StaticParam] {

  /** My type. */
  type Env = KindEnv

  /** My binding type. */
  type EnvBinding = KindBinding

  /** Creates a fresh kind environment. */
  def makeFresh: KindEnv = EmptyKindEnv.extend(Nil)

  /**
   * The bindings that the where clause's trait constraints give: each type
   * variable X named by a constraint X extends B, bound in the declared
   * bindings or outside them, rebound with B added to its bounds.
   */
  def constraintBounds(outer: KindEnv, declared: Iterable[KindBinding],
                       where: Option[WhereClause]): Iterable[KindBinding] = where match {
    case Some(SWhereClause(_, _, constraints)) =>
      val scope = new NestedKindEnv(outer, declared)
      val byName = constraints.collect { case SWhereExtends(_, name, supers) => (name, supers) }
      val names = byName.map(_._1).foldLeft(List[Id]())((acc, n) =>
        if (acc.exists(_.getText == n.getText)) acc else acc :+ n)
      names.flatMap(n => scope.lookup(n) match {
        case Some(KindBinding(bn, sp)) if sp.getKind.isInstanceOf[KindType] =>
          val extra = byName.filter(_._1.getText == n.getText).flatMap(_._2)
          val supers = toListFromImmutable(sp.getExtendsClause) ++ extra
          List(KindBinding(bn, NF.makeStaticParam(sp, sp.getName.asInstanceOf[Id], toJavaList(supers))))
        case _ => Nil
      })
    case _ => Nil
  }

  /** Extract out the bindings in node. */
  protected def extractNodeBindings(node: Node) : Iterable[KindBinding] =
    node match {
      // Trivially add this param.
      case p:StaticParam => Iterable(KindBinding(p.getName, p))

      // Extract bindings from generic declaration.
      case g:Generic =>

  case SComponent(info, name, imports, decls, comprises, isNative, exports) =>
    SComponent(info, name, imports,
               decls.map((n:Decl) => check(n).asInstanceOf[Decl]), comprises,
               isNative, exports)

  case t@STraitDecl(info,
                    STraitTypeHeader(sparams, mods, name, where,
                                     throwsC, contract, extendsC, params, decls),
                    selfType, excludes, comprises, hasEllipses) => {
    // A conditional extension's conditions hold while the members are checked.
    val checkerWSparams: STypeChecker =
      this.extend(sparams, params, staticenv.KindEnv.withExtendsConditions(where, extendsC))
    var method_checker = checkerWSparams
    var field_checker = checkerWSparams
    // Add field declarations (getters/setters?) to method_checker
    method_checker = decls.foldRight(method_checker)
                                    { (d:Decl, c:STypeChecker) => d match {
                                      case SVarDecl(_,lhs,_) => c.extend(lhs)
                                      case _ => c } }
    toOption(traits.typeCons(name.asInstanceOf[Id])) match {
      case None => signal(name, errorMsg(name, " is not found.")); t
      case Some(ti) =>
        // Extend method checker with methods and functions
        // that will now be in scope
        val inheritedMethods = commonInheritedMethods(extendsC, analyzer.traits)
        val dottedMethods = toSet(ti.asInstanceOf[TraitIndex].dottedMethods.secondSet)
        val methods = inheritedMethods ++ dottedMethods
        method_checker = method_checker.extendWithListOfFunctions(methods)
        // Extend method checker with self
        selfType match {
          case Some(ty) =>
            method_checker = method_checker.addSelf(ty)
            // Check declarations
            val newDecls = decls.map( (d:Decl) => d match {
                                      case SFnDecl(_,_,_,_,_) =>
                                        // methods see extra variables in scope
                                        method_checker.check(d).asInstanceOf[Decl]
                                      case SVarDecl(_,lhs,_) =>
                                        // fields see other fields
                                        val newD = field_checker.check(d).asInstanceOf[Decl]
                                        field_checker = field_checker.extend(lhs)
                                        newD
                                      case _ => checkerWSparams.check(d).asInstanceOf[Decl] } )
            STraitDecl(info,
                       STraitTypeHeader(sparams, mods, name, where,
                                        throwsC, contract, extendsC, params, newDecls),
                       selfType, excludes, comprises, hasEllipses)
          case _ => signal(t, errorMsg("Self type is not inferred for ", t)); t
        }
    }
  }

  case o@SObjectDecl(info,
                     STraitTypeHeader(sparams, mods, name, where,
                                      throwsC, contract, extendsC, params, decls),
                     selfType) => {
    // A conditional extension's conditions hold while the members are checked.
    val checkerWSparams: STypeChecker =
      this.extend(sparams, params, staticenv.KindEnv.withExtendsConditions(where, extendsC))
    var method_checker = checkerWSparams
    var field_checker = checkerWSparams
    val newContract = contract match {
      case Some(e) => Some(method_checker.check(e).asInstanceOf[Contract])
      case _ => contract
    }
    // Check method declarations.
    toOption(traits.typeCons(name.asInstanceOf[Id])) match {
      case None => signal(name, errorMsg(name, " is not found.")); o
      case Some(oi) =>
        // Extend type checker with methods and functions
        // that will now be in scope as regular functions
        val dottedMethods = toSet(oi.asInstanceOf[TraitIndex].dottedMethods.secondSet)
        val inheritedMethods = commonInheritedMethods(extendsC, analyzer.traits)
        val methods = inheritedMethods ++ dottedMethods
        method_checker = method_checker.extendWithListOfFunctions(methods)
        // Extend method checker with fields, over the methods: a naked
        // reference to a field reads the field, not a getter of its name
        method_checker = method_checker.extend(List[StaticParam](), params, None)
        method_checker = decls.foldRight(method_checker)
                                        { (d:Decl, c:STypeChecker) => d match {
                                          case SVarDecl(_,lhs,_) => c.extend(lhs)
                                          case _ => c } }
        // Extend method checker with self
        selfType match {
          case Some(ty) =>
            method_checker = method_checker.addSelf(ty)
            // Check declarations, storing them in the same order
            val newDecls = decls.map( (d:Decl) => d match {
                                      case SFnDecl(_,_,_,_,_) =>
                                        // Methods get some extra vars in their declarations
                                        method_checker.check(d).asInstanceOf[Decl]
                                      case SVarDecl(_,lhs,_) =>
                                        // Fields get to see earlier fields
                                        val newD = field_checker.check(d).asInstanceOf[Decl]
                                        field_checker = field_checker.extend(lhs)
                                        newD
                                      case _ => checkerWSparams.check(d).asInstanceOf[Decl] } )
            SObjectDecl(info,
               (implicit analyzer: TypeAnalyzer,
                         envCache: MMap[APIName, STypeEnv],
                         cycleChecker: CyclicReferenceChecker): STypeCheckerImpl

